#include <iostream>
#include <memory>
#include <vector>

// Example of breaking a cyclic dependency
struct Node {
    std::shared_ptr<Node> next;
    std::weak_ptr<Node> prev; // Use weak_ptr to break the cycle
    ~Node() { std::cout << "Node destroyed\n"; }
};

void demonstrate_cycle_breaking() {
    auto node1 = std::make_shared<Node>();
    auto node2 = std::make_shared<Node>();

    node1->next = node2;
    node2->prev = node1; // This weak link prevents a memory leak

    // If node2->prev were a shared_ptr, neither node1 nor node2 would be destroyed.
}

// Example of checking for an expired pointer (caching/observer use case)
std::weak_ptr<int> g_weak_observer;

void observe_resource() {
    auto resource = std::make_shared<int>(42);
    g_weak_observer = resource; // Observe the resource without owning it

    // Try to access the observed resource via lock()
    if (auto locked_ptr = g_weak_observer.lock()) {
        std::cout << "Resource is alive, value: " << *locked_ptr << "\n";
    } else {
        std::cout << "Resource is gone.\n";
    }
} // `resource` is destroyed here, its ref count goes to 0

int main() {
    std::cout << "--- Cycle Breaking Demo ---\n";
    demonstrate_cycle_breaking(); // Both nodes are destroyed correctly.

    std::cout << "\n--- Observer/Dangling Pointer Demo ---\n";
    observe_resource();

    // Try to access the resource again after it's been destroyed
    if (auto locked_ptr = g_weak_observer.lock()) {
        std::cout << "Resource is alive.\n";
    } else {
        std::cout << "Resource has been destroyed.\n";
    }
    return 0;
}
